#!/usr/bin/env python3# -*- coding: utf-8 -*-"""apophis_swarm_nav_modes_ekf_demo.py==================================Multi-deputy EKF demo for Apophis rendezvous bundles D0..D7 with selectablemeasurement modes:  MODE = "gps"            -> GPS-only (Hill state measurement)  MODE = "rr"             -> Range + range-rate only (nonlinear)  MODE = "gps+r"          -> GPS + range only  MODE = "gps+rr"         -> GPS + range + range-rateState (Hill / chief LVLH):  x = [ρ_R, ρ_T, ρ_N, ρ̇_R, ρ̇_T, ρ̇_N]^TExpected directory:  Scenario/Apophis/	  apophis_rendezvous_full_D0.npz	  ...	  apophis_rendezvous_full_D7.npz"""from __future__ import annotationsimport sysfrom pathlib import Pathfrom typing import Tuple, Dict, Listimport numpy as npimport numpy.linalg as laimport matplotlib.pyplot as plt# ──────────────────────────────────────────────────────────────────────────────#                               TOGGLES (TOP)# ──────────────────────────────────────────────────────────────────────────────MODE = "gps"          # "gps" | "rr" | "gps+r" | "gps+rr"N_DEP      = 8MEAS_DECIM = 100     # decimate truth to nav cadenceCROP_AFTER_DEPLOY_HR = 0.5# GPS-like measurement noise (Hill state measurement)GPS_SIGMA_POS = 3.0     # [m] 1σGPS_SIGMA_VEL = 0.03    # [m/s] 1σ# Range / range-rate measurement noise (assumed by filter)RANGE_SIGMA = 10.0      # [m] 1σRRATE_SIGMA = 0.02      # [m/s] 1σ# Optional dropout/outliers for range/range-rateP_RR_DROPOUT = 0.03P_RR_OUTLIER = 0.01OUTLIER_SCALE_R  = 8.0OUTLIER_SCALE_RR = 8.0# NIS gate thresholds# chi2_1: 10.83 ~ 99.9%   |   chi2_2: 13.82 ~ 99.9%NIS_GATE_R  = 10.83NIS_GATE_RR = 13.82# 3D ellipsoid plottingPLOT_ELLIPSOIDS = TrueELLIPSOID_NSTD  = 3.0ELLIPSOID_EVERY = 120ELLIPSOID_NPTS  = 12# Separate plots per deputyPLOT_SEPARATE_PER_DEP = True# ──────────────────────────────────────────────────────────────────────────────#                             locate ARISE root# ──────────────────────────────────────────────────────────────────────────────SCRIPT_DIR = Path(__file__).resolve().parentROOT = Nonefor parent in SCRIPT_DIR.parents:	if (parent / "GNC").is_dir():		ROOT = parent		breakif ROOT is None:	ROOT = SCRIPT_DIR.parents[2]if str(ROOT) not in sys.path:	sys.path.insert(0, str(ROOT))from GNC.Navigation.hill_ekf import (	HillEKF, HillEKFConfig,	dcm_lvlh, hill_rate)# ──────────────────────────────────────────────────────────────────────────────#                               bundle loading# ──────────────────────────────────────────────────────────────────────────────def load_apophis_bundle(path: Path) -> Dict[str, np.ndarray]:	wanted = (		"t", "rD_N", "vD_N", "rC_N", "vC_N",		"rA_N", "vA_N", "impulses"	)	out: Dict[str, np.ndarray] = {}	with np.load(path, allow_pickle=True) as npz:		for k in wanted:			if k in npz:				out[k] = npz[k]	if "impulses" not in out:		out["impulses"] = np.zeros((0, 4), dtype=float)	return outdef make_state_fn_from_bundle(data: Dict[str, np.ndarray], r_key: str, v_key: str):	t_arr = np.asarray(data["t"], float).reshape(-1)	r = np.asarray(data[r_key], float).reshape(-1, 3)	v = np.asarray(data[v_key], float).reshape(-1, 3)	def interp_vec(t: float, arr: np.ndarray) -> np.ndarray:		if t <= t_arr[0]:			return arr[0]		if t >= t_arr[-1]:			return arr[-1]		j = np.searchsorted(t_arr, t) - 1		f = (t - t_arr[j]) / (t_arr[j + 1] - t_arr[j] + 1e-15)		return (1.0 - f) * arr[j] + f * arr[j + 1]	def state_fn(t: float) -> Tuple[np.ndarray, np.ndarray]:		return interp_vec(t, r), interp_vec(t, v)	return state_fndef build_burn_sequence(impulses: np.ndarray, t_arr: np.ndarray, dt: float) -> np.ndarray:	impulses = np.asarray(impulses, float).reshape(-1, 4)	dv_seq = np.zeros((len(t_arr), 3))	if impulses.size == 0:		return dv_seq	impulses = impulses[np.argsort(impulses[:, 0])]	idx_imp = 0	for k, t in enumerate(t_arr):		while idx_imp < impulses.shape[0] and impulses[idx_imp, 0] < t - 0.5 * dt:			idx_imp += 1		if idx_imp < impulses.shape[0] and abs(impulses[idx_imp, 0] - t) <= 0.5 * dt:			dv_seq[k, :] = impulses[idx_imp, 1:4]			idx_imp += 1	return dv_seq# ──────────────────────────────────────────────────────────────────────────────#                             ECI <-> Hill helpers# ──────────────────────────────────────────────────────────────────────────────def hill_state_from_eci(rD_N, vD_N, rC_N, vC_N) -> np.ndarray:	rC = np.asarray(rC_N, float).reshape(3)	vC = np.asarray(vC_N, float).reshape(3)	rD = np.asarray(rD_N, float).reshape(3)	vD = np.asarray(vD_N, float).reshape(3)	C_HN = dcm_lvlh(rC, vC)  # Hill-from-ECI	r_rel_N = rD - rC	v_rel_N = vD - vC	rho = C_HN @ r_rel_N	omega_H = np.array([0.0, 0.0, hill_rate(rC, vC)])	v_rot = C_HN @ v_rel_N	rhod = v_rot - np.cross(omega_H, rho)	x = np.zeros(6)	x[0:3] = rho	x[3:6] = rhod	return xdef eci_to_hill_traj(rD_N, vD_N, rC_N, vC_N) -> np.ndarray:	N = np.asarray(rD_N).shape[0]	x_true = np.zeros((N, 6))	for k in range(N):		x_true[k] = hill_state_from_eci(rD_N[k], vD_N[k], rC_N[k], vC_N[k])	return x_true# ──────────────────────────────────────────────────────────────────────────────#                           measurement generators# ──────────────────────────────────────────────────────────────────────────────def build_gps_meas_hill(	rng: np.random.Generator,	rD_true: np.ndarray, vD_true: np.ndarray,	rC_true: np.ndarray, vC_true: np.ndarray,	sigma_pos: float = GPS_SIGMA_POS,	sigma_vel: float = GPS_SIGMA_VEL,) -> np.ndarray:	rD_true = np.asarray(rD_true, float)	vD_true = np.asarray(vD_true, float)	rC_true = np.asarray(rC_true, float)	vC_true = np.asarray(vC_true, float)	N = rD_true.shape[0]	z = np.zeros((N, 6))	for k in range(N):		rD_meas = rD_true[k] + sigma_pos * rng.normal(size=3)		vD_meas = vD_true[k] + sigma_vel * rng.normal(size=3)		z[k] = hill_state_from_eci(rD_meas, vD_meas, rC_true[k], vC_true[k])	return zdef build_range_rangerate_meas(	rng: np.random.Generator,	rD_true: np.ndarray, vD_true: np.ndarray,	rA_true: np.ndarray, vA_true: np.ndarray,	sigma_r: float = RANGE_SIGMA,	sigma_rr: float = RRATE_SIGMA,	p_dropout: float = P_RR_DROPOUT,	p_outlier: float = P_RR_OUTLIER,	outlier_scale_r: float = OUTLIER_SCALE_R,	outlier_scale_rr: float = OUTLIER_SCALE_RR,) -> Tuple[np.ndarray, np.ndarray]:	rD_true = np.asarray(rD_true, float)	vD_true = np.asarray(vD_true, float)	rA_true = np.asarray(rA_true, float)	vA_true = np.asarray(vA_true, float)	N = rD_true.shape[0]	z = np.zeros((N, 2))	valid = np.ones(N, dtype=bool)	for k in range(N):		r_rel = rD_true[k] - rA_true[k]		v_rel = vD_true[k] - vA_true[k]		rng_true = la.norm(r_rel)		if rng_true < 1e-9:			rr_true = 0.0		else:			rr_true = float(np.dot(r_rel, v_rel) / rng_true)		nr = sigma_r * rng.normal()		nrr = sigma_rr * rng.normal()		if rng.random() < p_outlier:			nr *= outlier_scale_r			nrr *= outlier_scale_rr		z[k, 0] = rng_true + nr		z[k, 1] = rr_true + nrr		if k == 0:			valid[k] = True		else:			valid[k] = (rng.random() >= p_dropout)	return z, valid# ──────────────────────────────────────────────────────────────────────────────#                 nonlinear prediction + Jacobian: range (+ rr)# ──────────────────────────────────────────────────────────────────────────────def _inertial_from_hill(x_H: np.ndarray, t: float, chief_state_fn):	x_H = np.asarray(x_H, float).reshape(6)	rho = x_H[0:3]	rhod = x_H[3:6]	rC, vC = chief_state_fn(t)	rC = np.asarray(rC, float).reshape(3)	vC = np.asarray(vC, float).reshape(3)	C_HN = dcm_lvlh(rC, vC)	A = C_HN.T	omega_H = np.array([0.0, 0.0, hill_rate(rC, vC)])	rD = rC + A @ rho	v_rot = rhod + np.cross(omega_H, rho)   # Hill	vD = vC + A @ v_rot	return rD, vD, C_HN, omega_Hdef range_pred_and_jacobian(	x_H: np.ndarray,	t: float,	chief_state_fn,	apophis_state_fn,) -> Tuple[float, np.ndarray]:	rD, _vD, C_HN, _omega_H = _inertial_from_hill(x_H, t, chief_state_fn)	rA, _vA = apophis_state_fn(t)	rA = np.asarray(rA, float).reshape(3)	r_rel = rD - rA	s = la.norm(r_rel)	u = np.zeros(3) if s < 1e-9 else (r_rel / s)	H = np.zeros((1, 6))	H[0, 0:3] = (C_HN @ u).reshape(3)  # ∂range/∂rho	return float(s), Hdef range_rangerate_pred_and_jacobian(	x_H: np.ndarray,	t: float,	chief_state_fn,	apophis_state_fn,) -> Tuple[np.ndarray, np.ndarray]:	rD, vD, C_HN, omega_H = _inertial_from_hill(x_H, t, chief_state_fn)	rA, vA = apophis_state_fn(t)	rA = np.asarray(rA, float).reshape(3)	vA = np.asarray(vA, float).reshape(3)	r_rel = rD - rA	v_rel = vD - vA	s = la.norm(r_rel)	if s < 1e-9:		u = np.zeros(3)		rng_hat = 0.0		rr_hat = 0.0	else:		u = r_rel / s		rng_hat = float(s)		rr_hat = float(np.dot(u, v_rel))	H = np.zeros((2, 6))	# range	cu = (C_HN @ u).reshape(3)	H[0, 0:3] = cu	# range-rate	if s >= 1e-9:		I3 = np.eye(3)		term1_inert = (I3 - np.outer(u, u)) @ v_rel		term1_hill = (C_HN @ term1_inert) / s		term2_hill = -np.cross(omega_H, cu)		H[1, 0:3] = term1_hill + term2_hill		H[1, 3:6] = cu	zhat = np.array([rng_hat, rr_hat], dtype=float)	return zhat, H# ──────────────────────────────────────────────────────────────────────────────#                               EKF update helpers# ──────────────────────────────────────────────────────────────────────────────def ekf_update_generic(ekf: HillEKF, z: np.ndarray, zhat: np.ndarray, H: np.ndarray, R: np.ndarray):	z = np.asarray(z, float).reshape(-1)	zhat = np.asarray(zhat, float).reshape(-1)	H = np.asarray(H, float)	R = np.asarray(R, float)	y = (z - zhat).reshape(-1, 1)	S = H @ ekf.P_pred @ H.T + R	K = ekf.P_pred @ H.T @ la.inv(S)	ekf.x = ekf.x_pred + (K @ y).reshape(-1)	I = np.eye(ekf.x.size)	if ekf.cfg.use_joseph:		KH = K @ H		ekf.P = (I - KH) @ ekf.P_pred @ (I - KH).T + K @ R @ K.T	else:		ekf.P = (I - K @ H) @ ekf.P_pred	ekf.y_pre = y.reshape(-1).copy()	ekf.S = S.copy()	ekf.H_last = H.copy()	ekf.y_post = ekf.y_pre.copy()def nis_value(y: np.ndarray, S: np.ndarray) -> float:	y = np.asarray(y, float).reshape(-1, 1)	S = np.asarray(S, float)	return float((y.T @ la.inv(S) @ y).reshape(()))# ──────────────────────────────────────────────────────────────────────────────#                           covariance ellipsoid plotting# ──────────────────────────────────────────────────────────────────────────────def plot_cov_ellipsoid(ax, mean: np.ndarray, cov: np.ndarray, n_std: float = 3.0, n_pts: int = 12):	mean = np.asarray(mean, float).reshape(3)	cov = np.asarray(cov, float).reshape(3, 3)	w, V = la.eigh(cov)	w = np.maximum(w, 0.0)	radii = n_std * np.sqrt(w)	u = np.linspace(0.0, 2.0 * np.pi, n_pts)	v = np.linspace(0.0, np.pi, n_pts)	xs = np.outer(np.cos(u), np.sin(v))	ys = np.outer(np.sin(u), np.sin(v))	zs = np.outer(np.ones_like(u), np.cos(v))	sphere = np.stack([xs, ys, zs], axis=0).reshape(3, -1)	ell = (V @ (radii.reshape(3, 1) * sphere)).reshape(3, xs.shape[0], xs.shape[1])	X = ell[0] + mean[0]	Y = ell[1] + mean[1]	Z = ell[2] + mean[2]	ax.plot_wireframe(X, Y, Z, rstride=2, cstride=2, linewidth=0.4)# ──────────────────────────────────────────────────────────────────────────────#                           run EKF for one deputy# ──────────────────────────────────────────────────────────────────────────────def run_ekf_for_deputy(dep_idx: int, data_dir: Path, meas_decim: int = MEAS_DECIM) -> Dict[str, np.ndarray]:	bundle_path = Path(data_dir) / f"apophis_rendezvous_full_D{dep_idx}.npz"	if not bundle_path.is_file():		raise FileNotFoundError(f"Missing bundle: {bundle_path}")	data = load_apophis_bundle(bundle_path)	t_full  = np.asarray(data["t"], float).reshape(-1)	rD_full = np.asarray(data["rD_N"], float).reshape(-1, 3)	vD_full = np.asarray(data["vD_N"], float).reshape(-1, 3)	rC_full = np.asarray(data["rC_N"], float).reshape(-1, 3)	vC_full = np.asarray(data["vC_N"], float).reshape(-1, 3)	rA_full = np.asarray(data["rA_N"], float).reshape(-1, 3)	vA_full = np.asarray(data["vA_N"], float).reshape(-1, 3)	impulses = np.asarray(data["impulses"], float).reshape(-1, 4)	# crop	t0 = float(t_full[0])	t_crop_start = t0 + CROP_AFTER_DEPLOY_HR * 3600.0	idx_crop = int(np.searchsorted(t_full, t_crop_start))	t_crop = t_full[idx_crop:]	# decimate	idx_decim = np.arange(0, len(t_crop), meas_decim)	idx_sel = idx_crop + idx_decim	t_arr  = t_full[idx_sel]	rD_sel = rD_full[idx_sel]	vD_sel = vD_full[idx_sel]	rC_sel = rC_full[idx_sel]	vC_sel = vC_full[idx_sel]	rA_sel = rA_full[idx_sel]	vA_sel = vA_full[idx_sel]	# burns	dt_full = float(np.median(np.diff(t_full)))	dv_full = build_burn_sequence(impulses, t_full, dt_full)	dv_seq_H = dv_full[idx_sel]	# truth in Hill	x_true = eci_to_hill_traj(rD_sel, vD_sel, rC_sel, vC_sel)	# interpolators	chief_state_fn   = make_state_fn_from_bundle(data, "rC_N", "vC_N")	apophis_state_fn = make_state_fn_from_bundle(data, "rA_N", "vA_N")	# EKF config	dt = float(np.median(np.diff(t_arr)))	cfg = HillEKFConfig(		dt=dt,		sigma_proc_pos=0.2,		sigma_proc_vel=5e-4,		sigma_meas_pos=GPS_SIGMA_POS,		sigma_meas_vel=GPS_SIGMA_VEL,		sigma_init_pos=1500.0 if MODE in ("rr",) else 500.0,  # RR-only often needs bigger init cov		sigma_init_vel=0.6 if MODE in ("rr",) else 0.3,		sigma_dv=0.02,		use_joseph=True,	)	ekf = HillEKF(cfg, chief_state_fn=chief_state_fn)	# init guess	x0_bias = np.array([250.0, -200.0, 120.0, 0.08, -0.06, 0.03])	x0_guess = x_true[0] + x0_bias	P0 = np.diag([		cfg.sigma_init_pos**2, cfg.sigma_init_pos**2, cfg.sigma_init_pos**2,		cfg.sigma_init_vel**2, cfg.sigma_init_vel**2, cfg.sigma_init_vel**2	])	# measurements	z_gps = None	if "gps" in MODE:		rng_gps = np.random.default_rng(1234 + 100 * dep_idx)		z_gps = build_gps_meas_hill(rng_gps, rD_sel, vD_sel, rC_sel, vC_sel)	z_rr = None	valid_rr = None	if MODE in ("rr", "gps+r", "gps+rr"):		rng_rr = np.random.default_rng(5678 + 100 * dep_idx)		z_rr, valid_rr = build_range_rangerate_meas(rng_rr, rD_sel, vD_sel, rA_sel, vA_sel)	R_gps = np.diag([		GPS_SIGMA_POS**2, GPS_SIGMA_POS**2, GPS_SIGMA_POS**2,		GPS_SIGMA_VEL**2, GPS_SIGMA_VEL**2, GPS_SIGMA_VEL**2	])	R_r  = np.array([[RANGE_SIGMA**2]])	R_rr = np.diag([RANGE_SIGMA**2, RRATE_SIGMA**2])	# run filter	ekf.reset(x0_guess, P0)	N = len(t_arr)	x_est = np.zeros((N, 6))	P_hist = np.zeros((N, 6, 6))	# optional innovation logs (for debugging)	y_r_hist  = np.full(N, np.nan)	y_rr_hist = np.full((N, 2), np.nan)	H_gps = np.eye(6)	ekf.x_pred = ekf.x.copy()	ekf.P_pred = ekf.P.copy()	ekf.t_last = float(t_arr[0])	for k in range(N):		t = float(t_arr[k])		if k > 0:			ekf.predict(t, burn_dv_H=dv_seq_H[k])		else:			ekf.x_pred = ekf.x.copy()			ekf.P_pred = ekf.P.copy()		# (A) GPS update		if "gps" in MODE:			zhat = ekf.x_pred.copy()			ekf_update_generic(ekf, z_gps[k], zhat, H_gps, R_gps)		# treat current state as pred for subsequent updates		ekf.x_pred = ekf.x.copy()		ekf.P_pred = ekf.P.copy()		# (B) Range-only update (if selected)		if MODE in ("gps+r",):			if valid_rr[k]:				zhat_r, H_r = range_pred_and_jacobian(ekf.x_pred, t, chief_state_fn, apophis_state_fn)				y = np.array([z_rr[k, 0] - zhat_r]).reshape(1, 1)				S = H_r @ ekf.P_pred @ H_r.T + R_r				nis = nis_value(y, S)				if nis <= NIS_GATE_R:					ekf_update_generic(ekf, np.array([z_rr[k, 0]]), np.array([zhat_r]), H_r, R_r)					y_r_hist[k] = ekf.y_pre[0]		# (C) Range + range-rate update (if selected)		if MODE in ("rr", "gps+rr"):			if valid_rr[k]:				zhat_rr, H_rr = range_rangerate_pred_and_jacobian(ekf.x_pred, t, chief_state_fn, apophis_state_fn)				y = (z_rr[k] - zhat_rr).reshape(-1, 1)				S = H_rr @ ekf.P_pred @ H_rr.T + R_rr				nis = nis_value(y, S)				if nis <= NIS_GATE_RR:					ekf_update_generic(ekf, z_rr[k], zhat_rr, H_rr, R_rr)					y_rr_hist[k, :] = ekf.y_pre.copy()		x_est[k] = ekf.x		P_hist[k] = ekf.P	# metrics	err = x_est - x_true	t_hr = (t_arr - t_arr[0]) / 3600.0	mask = t_hr >= 0.1	pos_err = err[mask, 0:3]	rms_axes = np.sqrt(np.mean(pos_err**2, axis=0))	rms_norm = np.sqrt(np.mean(np.sum(pos_err**2, axis=1)))	return dict(		dep_idx=dep_idx,		t_arr=t_arr,		t_hr=t_hr,		x_true=x_true,		x_est=x_est,		P_hist=P_hist,		y_r=y_r_hist,		y_rr=y_rr_hist,		rms_axes=rms_axes,		rms_norm=np.array([rms_norm], dtype=float),	)# ──────────────────────────────────────────────────────────────────────────────#                                    main# ──────────────────────────────────────────────────────────────────────────────def main():	data_dir = SCRIPT_DIR	print(f"=== Running EKF for all deputies with MODE='{MODE}' ===")	results: List[Dict[str, np.ndarray]] = []	for d in range(N_DEP):		print(f"\n----- Deputy {d} -----")		res = run_ekf_for_deputy(d, data_dir, meas_decim=MEAS_DECIM)		results.append(res)		ra = res["rms_axes"]		rn = float(res["rms_norm"][0])		print(f"RMS pos [R,T,N] = {ra[0]:.3f}, {ra[1]:.3f}, {ra[2]:.3f} m")		print(f"RMS pos norm    = {rn:.3f} m")	labels = ["R", "T", "N"]	if PLOT_SEPARATE_PER_DEP:		for res in results:			d = int(res["dep_idx"])			t_hr = res["t_hr"]			x_true = res["x_true"]			x_est  = res["x_est"]			P_hist = res["P_hist"]			err = x_est - x_true			pos_err = err[:, 0:3]			vel_err = err[:, 3:6]			Pdiag = np.diagonal(P_hist, axis1=1, axis2=2)			three_sigma = 3.0 * np.sqrt(np.maximum(Pdiag, 0.0))			mask = t_hr >= 0.1			tt = t_hr[mask]			# Fig 1: 3D traj + ellipsoids			fig1 = plt.figure(figsize=(10, 8))			ax1 = fig1.add_subplot(111, projection="3d")			ax1.plot(x_true[:, 0], x_true[:, 1], x_true[:, 2], linewidth=1.0, label="truth ρ")			ax1.plot(x_est[:, 0],  x_est[:, 1],  x_est[:, 2],  linewidth=1.0, label="est ρ")			if PLOT_ELLIPSOIDS and ELLIPSOID_EVERY > 0:				for k in range(0, x_est.shape[0], ELLIPSOID_EVERY):					Ppos = P_hist[k, 0:3, 0:3]					plot_cov_ellipsoid(ax1, x_est[k, 0:3], Ppos, n_std=ELLIPSOID_NSTD, n_pts=ELLIPSOID_NPTS)			ax1.set_xlabel("R [m]")			ax1.set_ylabel("T [m]")			ax1.set_zlabel("N [m]")			ax1.set_title(f"Deputy D{d}: Hill trajectory + {ELLIPSOID_NSTD:.0f}σ ellipsoids (MODE={MODE})")			ax1.grid(True)			ax1.legend()			# Fig 2: errors vs 3σ (scatter)			fig2, axes = plt.subplots(2, 3, figsize=(14, 7), sharex=True)			fig2.suptitle(f"Deputy D{d}: Errors vs 3σ (MODE={MODE})")			for i in range(3):				axp = axes[0, i]				axp.scatter(tt, pos_err[mask, i], s=6, alpha=0.45)				axp.plot(tt,  three_sigma[mask, i], linestyle="--", linewidth=1.0)				axp.plot(tt, -three_sigma[mask, i], linestyle="--", linewidth=1.0)				axp.set_title(f"ρ_{labels[i]}")				axp.set_ylabel("m")				axp.grid(True)			for i in range(3):				axv = axes[1, i]				axv.scatter(tt, vel_err[mask, i], s=6, alpha=0.45)				axv.plot(tt,  three_sigma[mask, 3 + i], linestyle="--", linewidth=1.0)				axv.plot(tt, -three_sigma[mask, 3 + i], linestyle="--", linewidth=1.0)				axv.set_title(f"ρ̇_{labels[i]}")				axv.set_ylabel("m/s")				axv.set_xlabel("Time since crop start [h]")				axv.grid(True)			fig2.tight_layout(rect=[0, 0, 1, 0.94])			# Optional Fig 3: innovations (only if RR/r enabled)			if MODE in ("rr", "gps+r", "gps+rr"):				y_r = res["y_r"]				y_rr = res["y_rr"]				fig3, ax = plt.subplots(2, 1, figsize=(12, 6), sharex=True)				fig3.suptitle(f"Deputy D{d}: Range innovations (accepted) (MODE={MODE})")				if MODE == "gps+r":					ax[0].scatter(tt, y_r[mask], s=6, alpha=0.45)					ax[0].plot(tt,  3.0 * RANGE_SIGMA * np.ones_like(tt), linestyle="--", linewidth=1.0)					ax[0].plot(tt, -3.0 * RANGE_SIGMA * np.ones_like(tt), linestyle="--", linewidth=1.0)					ax[0].set_ylabel("Range innov [m]")					ax[0].grid(True)					ax[1].axis("off")				else:					ax[0].scatter(tt, y_rr[mask, 0], s=6, alpha=0.45)					ax[0].plot(tt,  3.0 * RANGE_SIGMA * np.ones_like(tt), linestyle="--", linewidth=1.0)					ax[0].plot(tt, -3.0 * RANGE_SIGMA * np.ones_like(tt), linestyle="--", linewidth=1.0)					ax[0].set_ylabel("Range innov [m]")					ax[0].grid(True)					ax[1].scatter(tt, y_rr[mask, 1], s=6, alpha=0.45)					ax[1].plot(tt,  3.0 * RRATE_SIGMA * np.ones_like(tt), linestyle="--", linewidth=1.0)					ax[1].plot(tt, -3.0 * RRATE_SIGMA * np.ones_like(tt), linestyle="--", linewidth=1.0)					ax[1].set_ylabel("Range-rate innov [m/s]")					ax[1].set_xlabel("Time since crop start [h]")					ax[1].grid(True)				fig3.tight_layout(rect=[0, 0, 1, 0.94])		plt.show()	else:		plt.show()if __name__ == "__main__":	dep0_path = SCRIPT_DIR / "apophis_rendezvous_full_D0.npz"	if not dep0_path.is_file():		raise FileNotFoundError(			f"Expected Apophis bundle not found: {dep0_path}\n"			f"Run `basilik_rhig_apophis_rendezvous_fleet.py` first."		)	main()